/** Frozen, synthetic acceptance corpus. Gold questions are authored paraphrases,
 * not generated by the system being measured and not adjusted after a run.
 * Sixteen distinct people/projects per theme supply close semantic distractors.
 */
export const MEMORY_SCALE_CORPUS_VERSION = 'owner-cross-domain-v1';
export type ScaleCategory = 'identity' | 'shared' | 'world' | 'learning' | 'work' | 'values' | 'dream' | 'multilingual';
export interface ScaleDocument {
  key: string; category: ScaleCategory; text: string; tags: string[]; notebook: string;
  occurredAt: string; entrance: 'private' | 'group' | 'peer'; dream?: boolean;
}
export interface ScaleGoldQuery {
  id: string; category: ScaleCategory; text: string; expectedKeys: string[];
  /** Each group has alternative surface forms; all groups must be supported. */
  required: string[][]; forbidden?: string[]; noAnswer?: boolean; passive: boolean;
}
type Row = { text: string; query: string; required: string[][]; forbidden?: string[] };
type Theme = (c: { person: string; alias: string; project: string; color: string; n: number; i: number }) => Row;
